// backend/src/handlers/operacional.rs
use axum::{extract::{Path, State}, http::StatusCode, Json};
use sqlx::PgPool;
use crate::models::*;

pub async fn criar_contracheque(State(p): State<PgPool>, Json(b): Json<CriarContrachequeInput>) -> Result<(StatusCode, Json<String>), StatusCode> { let l = b.salario_bruto - b.descontos; if l < 0.0 { return Err(StatusCode::BAD_REQUEST); } let r = sqlx::query("INSERT INTO folha_pagamento (servidor_nome, matricula, mes_referencia, salario_bruto, descontos, salario_liquido) VALUES ($1, $2, $3, $4, $5, $6)").bind(&b.servidor_nome).bind(&b.matricula).bind(&b.mes_referencia).bind(b.salario_bruto).bind(b.descontos).bind(l).execute(&p).await; match r { Ok(_) => Ok((StatusCode::CREATED, Json("Ok".to_string()))), Err(_) => Err(StatusCode::CONFLICT) } }
pub async fn listar_contracheques(State(p): State<PgPool>) -> Result<Json<Vec<Contracheque>>, StatusCode> { Ok(Json(sqlx::query_as::<_, Contracheque>("SELECT id::text, servidor_nome, matricula, mes_referencia, salario_bruto::float8, descontos::float8, salario_liquido::float8 FROM folha_pagamento ORDER BY criado_em DESC").fetch_all(&p).await.unwrap())) }
pub async fn buscar_contracheques_servidor(State(p): State<PgPool>, Path(m): Path<String>) -> Result<Json<Vec<Contracheque>>, StatusCode> { Ok(Json(sqlx::query_as::<_, Contracheque>("SELECT id::text, servidor_nome, matricula, mes_referencia, salario_bruto::float8, descontos::float8, salario_liquido::float8 FROM folha_pagamento WHERE matricula = $1 ORDER BY mes_referencia DESC").bind(m).fetch_all(&p).await.unwrap())) }
pub async fn criar_solicitacao(State(p): State<PgPool>, Json(b): Json<CriarSolicitacaoInput>) -> Result<(StatusCode, Json<String>), StatusCode> { sqlx::query("INSERT INTO servidor_solicitacoes (matricula, tipo_solicitacao, data_inicio, data_fim) VALUES ($1, $2, $3::date, $4::date)").bind(&b.matricula).bind(&b.tipo_solicitacao).bind(&b.data_inicio).bind(&b.data_fim).execute(&p).await.unwrap(); Ok((StatusCode::CREATED, Json("Ok".to_string()))) }
pub async fn buscar_solicitacoes_servidor(State(p): State<PgPool>, Path(m): Path<String>) -> Result<Json<Vec<SolicitacaoServidor>>, StatusCode> { Ok(Json(sqlx::query_as::<_, SolicitacaoServidor>("SELECT id::text, matricula, tipo_solicitacao, data_inicio::text, data_fim::text, status FROM servidor_solicitacoes WHERE matricula = $1 ORDER BY criado_em DESC").bind(m).fetch_all(&p).await.unwrap())) }
pub async fn gerar_evento_esocial(State(p): State<PgPool>, Json(b): Json<CriarEventoInput>) -> Result<(StatusCode, Json<String>), StatusCode> { let xml_mock = format!("<eSocial><evento tipo=\"{}\"><matricula>{}</matricula></evento></eSocial>", b.tipo_evento, b.matricula); sqlx::query("INSERT INTO esocial_eventos (matricula, tipo_evento, xml_gerado) VALUES ($1, $2, $3)").bind(&b.matricula).bind(&b.tipo_evento).bind(xml_mock).execute(&p).await.unwrap(); Ok((StatusCode::CREATED, Json("Ok".to_string()))) }
pub async fn listar_eventos_esocial(State(p): State<PgPool>) -> Result<Json<Vec<EventoEsocial>>, StatusCode> { Ok(Json(sqlx::query_as::<_, EventoEsocial>("SELECT id::text, matricula, tipo_evento, xml_gerado, status, protocolo_retorno FROM esocial_eventos ORDER BY criado_em DESC").fetch_all(&p).await.unwrap())) }
pub async fn transmitir_evento_esocial(State(p): State<PgPool>, Path(id): Path<String>) -> Result<(StatusCode, Json<String>), StatusCode> { let p_mock = format!("PROT-GOVBR-{}", uuid::Uuid::new_v4().to_string().chars().take(8).collect::<String>().to_uppercase()); let r = sqlx::query("UPDATE esocial_eventos SET status = 'ENVIADO', protocolo_retorno = $1 WHERE id = $2::uuid AND status = 'AGUARDANDO_ENVIO'").bind(p_mock).bind(id).execute(&p).await.unwrap(); if r.rows_affected() == 0 { return Err(StatusCode::BAD_REQUEST); } Ok((StatusCode::OK, Json("Ok".to_string()))) }
pub async fn bater_ponto(State(p): State<PgPool>, Json(b): Json<CriarRegistroPontoInput>) -> Result<(StatusCode, Json<String>), StatusCode> { sqlx::query("INSERT INTO rh_ponto_eletronico (matricula, tipo_registro) VALUES ($1, $2)").bind(&b.matricula).bind(&b.tipo_registro).execute(&p).await.unwrap(); Ok((StatusCode::CREATED, Json("Ok".to_string()))) }
pub async fn listar_pontos(State(p): State<PgPool>) -> Result<Json<Vec<RegistroPonto>>, StatusCode> { Ok(Json(sqlx::query_as::<_, RegistroPonto>("SELECT id::text, matricula, tipo_registro, to_char(registrado_em, 'DD/MM/YYYY HH24:MI:SS') as registrado_em FROM rh_ponto_eletronico ORDER BY registrado_em DESC").fetch_all(&p).await.unwrap())) }
