pub async fn listar_bens(State(p): State<PgPool>) -> Result<Json<Vec<BemPatrimonial>>, StatusCode> { Ok(Json(sqlx::query_as::<_, BemPatrimonial>("SELECT id::text, codigo_tombamento, descricao, valor_aquisicao::float8, setor_alocacao, situacao FROM bens_patrimoniais ORDER BY criado_em DESC").fetch_all(&p).await.unwrap())) }
pub async fn criar_tributo(State(p): State<PgPool>, Json(b): Json<CriarTributoInput>) -> Result<(StatusCode, Json<String>), StatusCode> { sqlx::query("INSERT INTO tributos_lancamentos (contribuinte, tipo_tributo, exercicio, valor) VALUES ($1, $2, $3, $4)").bind(&b.contribuinte).bind(&b.tipo_tributo).bind(b.exercicio).bind(b.valor).execute(&p).await.unwrap(); Ok((StatusCode::CREATED, Json("Ok".to_string()))) }
