pub async fn emitir_nfse(State(p): State<PgPool>, Json(b): Json<CriarNotaFiscalInput>) -> Result<(StatusCode, Json<String>), StatusCode> { let v = b.valor_servico * (b.aliquota / 100.0); sqlx::query("INSERT INTO nfse_emissao (prestador_cnpj, tomador_cpf_cnpj, descricao_servico, valor_servico, aliquota, valor_issqn) VALUES ($1, $2, $3, $4, $5, $6)").bind(&b.prestador_cnpj).bind(&b.tomador_cpf_cnpj).bind(&b.descricao_servico).bind(b.valor_servico).bind(b.aliquota).bind(v).execute(&p).await.unwrap(); Ok((StatusCode::CREATED, Json("Ok".to_string()))) }
pub async fn listar_nfse(State(p): State<PgPool>) -> Result<Json<Vec<NotaFiscal>>, StatusCode> { Ok(Json(sqlx::query_as::<_, NotaFiscal>("SELECT id::text, numero_nota, prestador_cnpj, tomador_cpf_cnpj, descricao_servico, valor_servico::float8, aliquota::float8, valor_issqn::float8, status FROM nfse_emissao ORDER BY criado_em DESC").fetch_all(&p).await.unwrap())) }
pub async fn registrar_leitura(State(p): State<PgPool>, Json(b): Json<CriarLeituraInput>) -> Result<(StatusCode, Json<String>), StatusCode> { let c = b.leitura_atual - b.leitura_anterior; if c < 0.0 { return Err(StatusCode::BAD_REQUEST); } let v = if c <= 10.0 { 35.0 } else { 35.0 + ((c - 10.0) * 5.0) }; sqlx::query("INSERT INTO agua_leituras (matricula_imovel, leitura_anterior, leitura_atual, consumo_m3, valor_fatura) VALUES ($1, $2, $3, $4, $5)").bind(&b.matricula_imovel).bind(b.leitura_anterior).bind(b.leitura_atual).bind(c).bind(v).execute(&p).await.unwrap(); Ok((StatusCode::CREATED, Json("Ok".to_string()))) }
pub async fn listar_leituras(State(p): State<PgPool>) -> Result<Json<Vec<LeituraAgua>>, StatusCode> { Ok(Json(sqlx::query_as::<_, LeituraAgua>("SELECT id::text, matricula_imovel, leitura_anterior::float8, leitura_atual::float8, consumo_m3::float8, valor_fatura::float8, status FROM agua_leituras ORDER BY criado_em DESC").fetch_all(&p).await.unwrap())) }
